int bk7258_pcm_write(uint32_t session, const int16_t *samples, uint32_t count)
{
  int16_t block[BK7258_PCM_FRAME_SAMPLES];
  irqstate_t flags;
  uint32_t i;
  uint32_t ramp;
  uint32_t limited = 0;
