  if (ret < 0) return ret;
  flags = enter_critical_section();
  ret = pcm_validate(session);
  if (ret == 0 && g_pcm.status.capture) ret = -EPERM;
  if (ret == 0 && g_pcm.status.error) ret = g_pcm.status.error;
  if (ret == 0 && g_pcm.draining) ret = -EPIPE;
