+{
+  unsigned char bytes[16] = {16, 2};
+  if (!vendor || !length) return net_error(EINVAL);
+  if (native->sin_family != AF_INET) return net_error(EAFNOSUPPORT);
+  memcpy(bytes + 2, &native->sin_port, 2);
