+  if (flags & ~0x2b) return net_error(EOPNOTSUPP);
+  if (flags & 1) result |= MSG_PEEK;
+  if (flags & 2) result |= MSG_WAITALL;
+  if (flags & 8) result |= MSG_DONTWAIT;
+  if (flags & 32) result |= MSG_NOSIGNAL;
+  return result;
